// MARK: -

// MARK: - 1. Introduction
// Define a function to greet users.
func greet(_ name: String) -> String {
  return "Hello, \(name)!"
}

// Define a function to process a request.
func processRequest(_ request: Request) -> Response {
  // Perform some action based on the request.
  return Response(status: .success, body: "Hello, world!")
}

// MARK: - 2. Assistant
// Define an assistant class that implements the assistant pattern.
class Assistant: AssistantInterface {
  // MARK: Greet
  // Override this method to implement the greeting function.
  func greet(_ name: String) -> String {
    return greet(name: name)
  }

  // Override this method to implement the processing function.
  func processRequest(_ request: Request) -> Response {
    return processRequest(request: request)
  }

  // MARK: ProcessedResponse
  // Override this method to implement the handling of the response.
  func processedResponse(_ response: Response) -> String {
    switch response {
    case .success(let body):
      return body
    case .error(let error):
      return "An error occurred: \(error.localizedDescription)"
    }
  }
}

